{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Alpelisib, a highly transferable analogue, has an absolute oral bioavailability of about 68.7% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Encorafenib, another highly transferable analogue, is rapidly and nearly completely absorbed with an estimated bioavailability of at least 86%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Golidocitinib showed >80% oral bioavailability in a human radiolabeled mass balance study, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, the lowest measured analogue, still has an absolute bioavailability of 25.3%, above the 20% threshold, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tazemetostat, a moderately absorbed analogue, has absolute bioavailability of 31.8–33.9%, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable experimental analogues have absolute oral bioavailability at or above 25%, exceeding the F≥20% threshold; therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule.",
    "The query is a large symmetric dimer with multiple H-bond donors; its permeability and solubility may differ from the smaller analogues.",
    "Fasted-state-specific pharmacokinetic data for the query are not directly available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

